import java.util.*;
import java.io.*;

public class c {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        Circle[] circles = new Circle[n];
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            circles[i] = new Circle(new Vec(Integer.parseInt(parts[0]), Integer.parseInt(parts[1])), Integer.parseInt(parts[2]));
        }
        ArrayList<Vec> points = new ArrayList<>();
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        int result = 1;
        for (int i = 0; i < n; i++) {
            ArrayList<Vec> newPoints = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                Vec[] intersections = circles[i].intersect(circles[j]);
                if (intersections == null) continue;
                int a = parent[i] = parent[parent[i]];
                int b = parent[j] = parent[parent[j]];
                parent[a] = b;
                for (Vec v : intersections) {
                    boolean exists = false;
                    for (Vec e : newPoints) {
                        if (v.equals(e)) {
                            exists = true;
                            break;
                        }
                    }
                    if (!exists) newPoints.add(v);
                }
            }
            result += newPoints.size();
            outer: for (Vec v : newPoints) {
                for (Vec e : points) {
                    if (v.equals(e)) continue outer;
                }
                points.add(v);
            }
        }
        result -= points.size();
        for (int i = 0; i < n; i++) {
            result += 1 - Math.abs(Integer.signum(i - parent[i]));
        }
        System.out.println(result);
    }

    static class Circle {
        Vec center;
        double radius;

        public Circle(Vec c, double r) {
            this.center = c;
            this.radius = r;
        }

        public Vec[] intersect(Circle o) {
            if (center.equals(o.center)) return null;
            Vec dir = o.center.sub(center);
            double d2 = dir.mag2();
            double d = Math.sqrt(d2);
            if (radius + o.radius < d || radius + d < o.radius || o.radius + d < radius)
                return null;
            if (Vec.eq(radius + o.radius, d) || Vec.eq(o.radius + d, radius))
                return new Vec[] { center.add(dir.scale(radius / d)) };
            if (Vec.eq(radius + d, o.radius))
                return new Vec[] { center.sub(dir.scale(radius / d)) };
            double d1 = (radius * radius + d2 - o.radius * o.radius) / (2 * d);
            double h = Math.sqrt(radius * radius - d1 * d1);
            Vec unitDir = dir.unit();
            Vec rInt = center.add(unitDir.scale(d1).add(unitDir.rot270().scale(h)));
            Vec lInt = center.add(unitDir.scale(d1).add(unitDir.rot90().scale(h)));
            return new Vec[] { rInt, lInt };
        }
    }

    static class Vec {
        static final double EPS = 1e-9;
        double x, y;

        public Vec(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public Vec add(Vec o) {
            return new Vec(x + o.x, y + o.y);
        }

        public Vec sub(Vec o) {
            return new Vec(x - o.x, y - o.y);
        }

        public Vec scale(double s) {
            return new Vec(x * s, y * s);
        }

        public double dot(Vec o) {
            return x * o.x + y * o.y;
        }

        public double cross(Vec o) {
            return x * o.y - y * o.x;
        }

        public double mag2() {
            return dot(this);
        }

        public double mag() {
            return Math.sqrt(mag2());
        }

        public Vec unit() {
            return scale(1 / mag());
        }

        public Vec rot90() {
            return new Vec(-y, x);
        }

        public Vec rot270() {
            return new Vec(y, -x);
        }

        public boolean equals(Object o) {
            if (!(o instanceof Vec)) return false;
            Vec v = (Vec) o;
            return eq(x, v.x) && eq(y, v.y);
        }

        public String toString() {
            return "(" + String.format("%.2f", x) + ", " + String.format("%.2f", y) + ")";
        }

        static boolean eq(double a, double b) {
            return Math.abs(a - b) < EPS;
        }
    }
}
